<template><ManagementShell><section class="grid gap-4"><header><p class="bm-kicker">Suporte</p><h1 class="mt-2 font-display text-3xl font-black uppercase">Tickets</h1></header><article v-for="ticket in tickets" :key="ticket.id" class="bm-panel grid gap-3 rounded-md p-4 lg:grid-cols-[1fr_220px]"><div><span class="text-xs font-black text-ember">{{ ticket.status }} · {{ ticket.category }}</span><h2 class="mt-2 font-display text-xl font-black">{{ ticket.subject }}</h2><p class="mt-2 text-sm text-white/60">{{ ticket.message }}</p><p class="mt-2 text-xs text-white/45">Jogador: {{ ticket.account?.username }}</p></div><div class="grid gap-2"><textarea v-model="responses[ticket.id]" class="bm-admin-field min-h-20" placeholder="Resposta"></textarea><button class="bm-admin-primary" type="button" @click="resolve(ticket)">Responder e resolver</button></div></article><p v-if="!tickets.length" class="bm-panel rounded-md p-8 text-center text-sm text-white/45">Nenhum ticket pendente.</p></section></ManagementShell></template>
<script setup lang="ts">import type {SupportTicket} from '~/composables/useSupportApi';const api=useSupportApi();const tickets=ref<SupportTicket[]>([]);const responses=reactive<Record<string,string>>({});const load=async()=>{try{tickets.value=await api.adminTickets()}catch{tickets.value=[]}};const resolve=async(t:SupportTicket)=>{const response=responses[t.id]?.trim();if(!response)return;await api.updateTicket(t.id,{status:'RESOLVED',response,reason:'Resposta do suporte administrativo'});await load()};onMounted(load);useSeoMeta({title:'Tickets'})</script>
